package halotukozak
package alpaca
package internal
package lexer

import halotukozak.alpaca.ErrorHandling.Strategy
import halotukozak.regex.TokenMatcher

import scala.NamedTuple.AnyNamedTuple
import scala.annotation.publicInBinary
import scala.collection.mutable

/**
 * The result of compiling a lexer definition.
 *
 * This abstract class represents a compiled lexer that can tokenize input.
 * It is generated by the `lexer` macro and provides methods to access tokens
 * and perform tokenization.
 *
 * @tparam Ctx the global context type
 */
transparent abstract class Lexer[Ctx <: LexerCtx] @publicInBinary private[alpaca] (
  onTokenMatch: (Token[?, Ctx, ?], String, Ctx) => Ctx,
  initialCtx: () => Ctx,
)(using errorHandling: ErrorHandling[Ctx],
) extends Selectable:
  /** The lexer's tokens by name, as a named tuple: what `MyLexer.NAME` selects. */
  type Fields <: AnyNamedTuple

  /** The context fields every lexeme and error of this lexer carries, as a named tuple. */
  final type LexemeFields = NamedTuple.From[Ctx]

  /** A lexeme of this lexer, with its context fields: `def show(lexeme: MyLexer.Lexeme)`. */
  final type Lexeme = lexer.Lexeme[?, ?] withFields LexemeFields

  /** An error of this lexer, with its context fields: `def report(error: MyLexer.LexerError)`. */
  final type LexerError = alpaca.LexerError withFields LexemeFields

  /** An error of a parser run on this lexer's lexemes, with their context fields: `def report(error: MyLexer.ParserError)`. */
  final type ParserError = alpaca.ParserError withFields LexemeFields

  /** All tokens defined in this lexer, including ignored tokens, in priority order; `selectDynamic` reads them by index. */
  @publicInBinary
  private[alpaca] def tokens: IArray[Token[?, Ctx, ?]]

  /** Backs token selection by name (`myLexer.PLUS`); not meant to be called directly. */
  def selectDynamic(fieldName: String): Token[?, Ctx, ?]

  /**
   * Tokenizes the input character sequence.
   *
   * Processes the input from start to finish, matching tokens and building
   * a list of lexemes. Input that matches no token does not throw: it is
   * reported as a [[LexerError]], and the context's [[ErrorHandling]] decides
   * whether tokenizing stops there or skips it and goes on. An exception thrown
   * by a rule body, such as a failed `require`, propagates out of `tokenize`.
   *
   * @param input the input to tokenize
   * @return the lexemes and the final lexer context, or the errors if any input did not match; with a recovering
   *         strategy the lexemes collected despite the errors are the failure's `recovered` value
   */
  final def tokenize(input: CharSequence): Result[Ctx, List[Lexeme], LexerError] = {
    var globalCtx = initialCtx()
    globalCtx.input = input match
      case reader: LazyReader => reader
      case _ => OffsetCharSequence(input)

    val acc = mutable.ListBuffer.empty[Lexeme]
    val errors = mutable.ListBuffer.empty[LexerError]
    var stopped = false

    while !globalCtx.input.isEmpty do {
      val step: Step[Ctx] = matcher.matchAt(globalCtx.input, 0) match {
        case m if m != null && m.end > 0 =>
          val matchedStr = globalCtx.input.subSequence(0, m.end).toString
          globalCtx.lastRawMatched = matchedStr
          val found = tokens(m.priority)
          globalCtx.input = globalCtx.input.from(m.end)
          Step.Matched(found)

        case _ =>
          val cpLen = Character.charCount(Character.codePointAt(globalCtx.input, 0))
          val unexpected =
            alpaca.LexerError[LexemeFields](globalCtx.input.subSequence(0, cpLen).toString, fieldNames, globalCtx)
          val handled = errorHandling.handle(globalCtx, unexpected)
          globalCtx = handled.ctx
          handled.strategy match {
            case Strategy.SkipToNextMatch =>
              val skipped =
                matcher.findFirst(globalCtx.input, cpLen).fold(cpLen)((firstMatching, _, _) => firstMatching)
              val matchedStr = globalCtx.input.subSequence(0, skipped).toString
              // a handler assigns `var` fields in place, so keep the fields `unexpected` read before it
              errors += new alpaca.LexerError(matchedStr, fieldNames, unexpected.fieldValues).asInstanceOf[LexerError]
              globalCtx.lastRawMatched = matchedStr
              globalCtx.input = globalCtx.input.from(skipped)
              Step.Matched(RecoveredToken(matchedStr))

            case Strategy.SkipOne =>
              val matchedStr = unexpected.unexpected
              errors += unexpected
              globalCtx.lastRawMatched = matchedStr
              globalCtx.input = globalCtx.input.from(cpLen)
              Step.Matched(RecoveredToken(matchedStr))

            case Strategy.Stop =>
              errors += unexpected
              stopped = true
              globalCtx.input = ""
              Step.Stopped
          }
      }

      if !step.isStopped then
        val token = step.asToken
        // every step that matches stores its text in `lastRawMatched`
        globalCtx = onTokenMatch(token, globalCtx.lastRawMatched, globalCtx)
        if token.isInstanceOf[DefinedToken[?, Ctx, ?, ?]] then acc.addOne(globalCtx.lastLexeme.nn.asInstanceOf[Lexeme])
    }

    errors.toList match
      case Nil => Result.Success(globalCtx, acc.toList)
      case first :: rest => Result.Failure(globalCtx, Option.unless(stopped)(acc.toList), ::(first, rest))
  }

  /** Compiled token-matcher; built at macro time. */
  @publicInBinary
  private[alpaca] def matcher: TokenMatcher

  private val fieldNames: Array[String] = initialCtx().productElementNames.toArray

/**
 * The outcome of one step of [[Lexer.tokenize]]: a token matched (or recovered), or a stop. Opaque over the token so
 * that a step allocates nothing; the matched text is the context's `lastRawMatched`.
 */
opaque private type Step[Ctx <: LexerCtx] = Token[?, Ctx, ?] | Null

private object Step:
  def Matched[Ctx <: LexerCtx](token: Token[?, Ctx, ?]): Step[Ctx] = token
  def Stopped[Ctx <: LexerCtx]: Step[Ctx] = null

  extension [Ctx <: LexerCtx](step: Step[Ctx])
    def isStopped: Boolean = step == null
    def asToken: Token[?, Ctx, ?] = step.nn

extension (input: CharSequence)
  private[alpaca] def from(pos: Int): CharSequence = input match
    case ocs: OffsetCharSequence => ocs.from(pos)
    case lfr: LazyReader => lfr.from(pos)
    case _ => input.subSequence(pos, input.length)
